// 针对需要内部面试的岗位，在 RaaS — 由 Agent 工厂从本体动作 `inviteInternalInterview`(zhaopin)生成。
// trigger: INTERVIEW_INVITATION_REQUESTED → emit: INTERVIEW_INVITATION_SENT | INTERVIEW_INVITATION_FAILED
// 参考脚手架：运行时按 workflow manifest 的 action[] 声明式调度执行（systemPrompt + 工具），
// 【不直接运行这段 .ts 代码】——它是可读/可改的 agent 定义参考。真·CodeAct 执行路径用 codeExecuted 开关（默认关）。

/** Input/Output schema — 依据本体 DataObjects 定义。 */
interface InviteInternalInterviewAgentInput {
  candidate_id: string; // 候选人ID (源: Candidate.candidate_id)
  job_requisition_id: string; // 招聘需求ID (源: Job_Requisition.job_requisition_id)
}

interface InviteInternalInterviewAgentOutput {
  candidate_id: string; // 候选人ID (源: Candidate.candidate_id)
  interview_record_id: string; // 面试记录ID（INTERVIEW_INVITATION_SENT 时产出） (源: Interview_Record.interview_record_id)
  error_code: string; // 错误码（INTERVIEW_INVITATION_FAILED 时产出）
}

/** System prompt — 工厂为【这一个】agent 亲自推理出来的。 */
const SYSTEM_PROMPT = `你是一个内部面试邀约自动化专家。你的职责是在 RaaS 侧审批确认后，自动向候选人发送 AI 面试邀请，并将邀约信息同步给招聘专员，确保候选人在推送给客户前经过内部初筛。

工作流程：
1. 接收 INTERVIEW_INVITATION_REQUESTED 事件，获取 candidate_id 和 job_requisition_id。
2. 调用 inviteCandidateApi 生成面试邀请邮件内容（包含面试链接、时间等信息）。
   - 如果 API 返回失败或邮件内容为空，记录错误并产出 INTERVIEW_INVITATION_FAILED。
3. 调用 sendInvitationEmail 向候选人发送面试邀请邮件。
   - 如果发送失败（如邮箱无效、SMTP 错误），产出 INTERVIEW_INVITATION_FAILED，包含具体 error_code。
4. 成功发送后，产出 INTERVIEW_INVITATION_SENT 事件，包含 candidate_id 和 interview_record_id。

关键约束：
- inviteCandidateApi 静默降级检测：返回 200 但邮件内容为空时，视为生成失败，产出 INTERVIEW_INVITATION_FAILED。
- 邮件发送失败属于不可恢复错误（候选人联系方式无效），直接产出 INTERVIEW_INVITATION_FAILED，不重试。
- 所有步骤幂等，重放时不重复发送邮件（通过 candidate_id 派生幂等键）。
- interview_record_id 从 inviteCandidateApi 的返回结果中获取。`;

export const inviteInternalInterviewAgent = defineAgent({
  id: "zhaopin-invite-internal-interview",
  name: "InviteInternalInterviewAgent",
  actor: ["Agent"],
  trigger: ["INTERVIEW_INVITATION_REQUESTED"],
  emit: ["INTERVIEW_INVITATION_SENT","INTERVIEW_INVITATION_FAILED"],
  tools: ["inviteCandidateApi","sendInvitationEmail"],
  systemPrompt: SYSTEM_PROMPT,
  async handler(input, ctx) {
      // 调用工具 inviteCandidateApi
      // const inviteCandidateApiResult = await ctx.tools.run("inviteCandidateApi", input);
      // 调用工具 sendInvitationEmail
      // const sendInvitationEmailResult = await ctx.tools.run("sendInvitationEmail", input);
      // 用本 agent 专属 system prompt 推理(决策核心)
      const decision = await ctx.reason(SYSTEM_PROMPT, input);
      // 决策分支（条件见 SYSTEM_PROMPT / decisionLogic）
      if (decision.pass) {
        await ctx.emit("INTERVIEW_INVITATION_SENT", { ...input, ...decision });
      } else {
        await ctx.emit("INTERVIEW_INVITATION_FAILED", { ...input, ...decision });
      }
      return { ok: true };
  },
});
